    vi.mocked(repo.getChangeLogEntry).mockResolvedValue(deleteEntry);
    const auditError = new Error('Append failure');
    vi.mocked(repo.appendChangeLog).mockRejectedValue(auditError);

    const res = await call();

    expect(res.status).toBe(200);
    expect(res.body.warning).toBe('Audit log entry could not be written');
  });

  it.each([
    ['POST /library/virtues', () => request(appAs(true)).post('/library/virtues').send({ Name: 'X' })],
    ['PUT /library/virtues/v-might', () => request(appAs(true)).put('/library/virtues/v-might').send({ Name: 'Y' })],
    ['DELETE /library/virtues/v-might', () => request(appAs(true)).delete('/library/virtues/v-might')],
    ['PUT /library/settings', () => request(appAs(true)).put('/library/settings').send({ PotentialTrackLength: 5 })],
    ['POST /library/import', () => request(appAs(true)).post('/library/import').send({ library: makeLibrary() })],
    ['POST /library/reset', () => request(appAs(true)).post('/library/reset')],
  ])( 'includes no warning when appendChangeLog succeeds on %s', async (_label, call) => {
